import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import {resolve} from 'node:path';
import {createHash} from 'node:crypto';
import vm from 'node:vm';
import {jsSources,root} from '../../../tools/support/crysta-headless-environment.mjs';
import {createHeadlessTransport} from '../../../tools/support/crysta-headless-transport.mjs';
const [variant,mode,inputFile]=process.argv.slice(2);
const sourceRoot=root;
const transport=createHeadlessTransport(resolve(`src-tauri/target/dramatic-bound/${variant}.exe`));
const hash=x=>createHash('sha256').update(x).digest('hex');
try {
 const context={console,__TAURI__:{core:transport.core}};context.window=context;vm.createContext(context);
 const worker=await readFile(resolve(sourceRoot,'assets/js/optimization/solver-worker.js'),'utf8');
 vm.runInContext(worker.match(/const BASE_ASPD_MAP = \{[^}]+\};/u)[0],context);
 for(const source of jsSources)vm.runInContext(await readFile(resolve(sourceRoot,'assets/js',source),'utf8'),context,{filename:source});
 const profile={};let prepared;const optimizer=context.ToramCrystaOptimizationGlobalOptimizer;
 context.ToramCrystaOptimizationGlobalOptimizer={...optimizer};
 for(const name of ['deriveRelevantKeys','prepareProblem'])context.ToramCrystaOptimizationGlobalOptimizer[name]=function(...args){const start=performance.now();try{const out=optimizer[name](...args);if(name==='prepareProblem')prepared=out;return out;}finally{profile[name+'Ms']=performance.now()-start;}};
 const fixture=JSON.parse(await readFile(inputFile,'utf8'));const input=fixture.resolvedExecutionContext||fixture;
 const started=performance.now();
 const scenario=context.ToramBuildEvaluator.createScenarioSnapshot(input.baseContext,{requirements:input.scenarioRequirements});
 const problem=context.ToramCrystaOptimizationProblemCompiler.compileCrystaProblem({registry:context.ToramStatRegistry,crystas:input.crystas||vm.runInContext('crystaDataJson',context),baseContext:input.baseContext,scenarioSnapshot:scenario,currentCrystas:input.currentCrystas||[],locks:input.locks||[],banned:input.banned||{},excluded:input.excluded||[],keepLowerUpgrades:Boolean(input.keepLowerUpgrades)});
 profile.compileMs=performance.now()-started;
 const result=await context.ToramCrystaOptimizationNativeClient.optimize(problem,{}, {timeLimitMs:30000,progressIntervalMs:32,maxParetoComparisons:1000000});
 profile.totalMs=performance.now()-started;profile.nativeMs=result.elapsedMs;
 assert.equal(result.status,'exact');assert.equal(result.exact,true);assert.equal(result.score,result.upperBound);
 assert.equal(result.outcomes.constraints.feasible,true);assert.equal(result.outcomes.damage.expected,result.score);
 const raw={};for(const p of result.bestBuild.packages)for(const [k,v] of Object.entries(p.statDelta))raw[k]=(raw[k]||0)+v;
 assert.deepEqual(raw,result.bestBuild.statDelta);
 console.log(JSON.stringify({profile,score:result.score,status:result.status,bestBuild:result.bestBuild,compiledHash:hash(JSON.stringify(problem)),preparedHash:hash(JSON.stringify(prepared)),visitedNodes:result.visitedNodes,evaluations:result.evaluations,enumeratedCompletions:result.enumeratedCompletions,metadata:transport.metadata,costProfile:variant==='profile'?await transport.core.invoke('crysta_cost_profile'):null}));
}finally{await transport.close();}

