$ErrorActionPreference='Stop'
$taskDir=Join-Path (Get-Location) 'src-tauri/target/dramatic-bound'
$nodeExe=(Get-Command node).Source
$rows=@()
$suites=@(
 @{fixture='saved-revenir';mode='release';input='tools/fixtures/crysta-saved-sword-shield-revenir-etowal.json'},
 @{fixture='saved-normal';mode='release';input='src-tauri/target/general-upper-bound/saved-normal.json'},
 @{fixture='saved-unlocked';mode='release';input='tools/fixtures/crysta-saved-sword-shield-revenir-unlocked.json'},
 @{fixture='old-revenir';mode='release';input='tools/fixtures/crysta-native-runtime-26min-revenir.json'},
 @{fixture='old-locked';mode='release';input='src-tauri/target/constrained-upper-bound/revenir-locked.json'}
)
foreach($suite in $suites){foreach($repeat in 1..10){
 $variants=if($repeat%2){@('before','after')}else{@('after','before')}
 foreach($variant in $variants){
  if(@($rows | Where-Object { $_.fixture -eq $suite.fixture -and $_.variant -eq $variant -and $_.repeat -eq $repeat }).Count -gt 0){continue}
  $prefix="$($suite.fixture)-$variant-$repeat"
  $outFile=Join-Path $taskDir "$prefix.out.json"
  $errFile=Join-Path $taskDir "$prefix.err.txt"
  $sample=Join-Path $taskDir 'sample.mjs'
  $inputFile=Join-Path (Get-Location) $suite.input
  $args='"'+$sample+'" '+$variant+' '+$suite.mode+' "'+$inputFile+'"'
  $taskProcess=Start-Process -FilePath $nodeExe -ArgumentList $args -WindowStyle Hidden -PassThru -RedirectStandardOutput $outFile -RedirectStandardError $errFile
  $peak=0L;$started=[DateTime]::UtcNow
  $binary=Join-Path $taskDir "$variant.exe"
  while(-not $taskProcess.HasExited){
   if(([DateTime]::UtcNow-$started).TotalSeconds-gt 180){throw 'Benchmark watchdog expired'}
   foreach($native in @(Get-Process -Name $variant -ErrorAction SilentlyContinue)){if($native.Path-eq $binary){$peak=[Math]::Max($peak,$native.PeakWorkingSet64)}}
   Start-Sleep -Milliseconds 25;$taskProcess.Refresh()
  }
  if($taskProcess.ExitCode-ne 0){throw (Get-Content -Raw $errFile)}
  $value=Get-Content -Raw $outFile|ConvertFrom-Json
  $rows+=[pscustomobject]@{fixture=$suite.fixture;mode=$suite.mode;variant=$variant;repeat=$repeat;nativePeakWorkingSetBytes=$peak;sample=$value}
  $rows|ConvertTo-Json -Depth 100|Set-Content -Encoding utf8 (Join-Path $taskDir 'comparisons.json')
  Write-Output "$prefix : visits=$($value.visitedNodes) evals=$($value.evaluations) total=$([Math]::Round($value.profile.totalMs,1)) native=$($value.profile.nativeMs) peak=$peak"
 }
}}

