import assert from 'node:assert/strict';
import {readFile,writeFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import {cpus} from 'node:os';
import {resolve} from 'node:path';
import {jsSources} from '../../../tools/support/crysta-headless-environment.mjs';
const dir='src-tauri/target/dramatic-bound';
const read=async p=>JSON.parse((await readFile(p,'utf8')).replace(/^\uFEFF/,''));
const hash=x=>createHash('sha256').update(x).digest('hex');
const normalized=async p=>(await readFile(p,'utf8')).replaceAll('\r\n','\n');
const rows=await read(`${dir}/comparisons.json`);
assert.equal(rows.length,100);
const inputs={
 'saved-revenir':'tools/fixtures/crysta-saved-sword-shield-revenir-etowal.json',
 'saved-normal':'src-tauri/target/general-upper-bound/saved-normal.json',
 'saved-unlocked':'tools/fixtures/crysta-saved-sword-shield-revenir-unlocked.json',
 'old-revenir':'tools/fixtures/crysta-native-runtime-26min-revenir.json',
 'old-locked':'src-tauri/target/constrained-upper-bound/revenir-locked.json'
};
const stats=a=>{const b=[...a].sort((x,y)=>x-y);return {mean:a.reduce((s,x)=>s+x,0)/a.length,median:(b[4]+b[5])/2,p95:b[Math.ceil(b.length*.95)-1],min:b[0],max:b.at(-1)};};
const summary={};
for(const fixture of Object.keys(inputs)){
 const runs=rows.filter(r=>r.fixture===fixture);assert.equal(runs.length,20);
 const first=runs[0].sample;
 for(const {sample} of runs){
  assert.equal(sample.status,'exact');assert.equal(sample.score,first.score);
  assert.deepEqual(sample.bestBuild,first.bestBuild);
  assert.equal(sample.compiledHash,first.compiledHash);
  assert.equal(sample.preparedHash,first.preparedHash);
 }
 const byVariant={};
 for(const variant of ['before','after']){
  const selected=runs.filter(r=>r.variant===variant);assert.equal(selected.length,10);
  byVariant[variant]=Object.fromEntries(['totalMs','nativeMs','compileMs','deriveRelevantKeysMs','prepareProblemMs'].map(k=>[k,stats(selected.map(r=>r.sample.profile[k]))]));
  for(const k of ['visitedNodes','evaluations','enumeratedCompletions'])byVariant[variant][k]=stats(selected.map(r=>r.sample[k]));
  assert.ok(selected.every(r=>r.nativePeakWorkingSetBytes>0));
  byVariant[variant].nativePeakWorkingSetBytes=stats(selected.map(r=>r.nativePeakWorkingSetBytes));
 }
 summary[fixture]={score:first.score,bestBuildId:first.bestBuild.id,compiledHash:first.compiledHash,preparedHash:first.preparedHash,...byVariant};
 for(const k of ['totalMs','nativeMs','visitedNodes','evaluations','nativePeakWorkingSetBytes']){
  summary[fixture][k+'ReductionPercent']=100*(1-byVariant.after[k].mean/byVariant.before[k].mean);
 }
}
const stamps={before:await read(`${dir}/before-build.json`),after:await read(`${dir}/after-build.json`)};
for(const variant of ['before','after'])assert.equal(hash(await readFile(`${dir}/${variant}.exe`)),stamps[variant].binaryHash);
for(const [path,h]of Object.entries(stamps.after.sources))assert.equal(hash(await normalized(path)),h,`Final source differs: ${path}`);
const inputRecords={};
for(const [fixture,path]of Object.entries(inputs))inputRecords[fixture]={path,sha256:hash(await readFile(path)),fixture:await read(path)};
const jsHashes={};
for(const p of [...jsSources.map(f=>'assets/js/'+f),'assets/js/optimization/solver-worker.js','tools/support/crysta-headless-environment.mjs','tools/support/crysta-headless-transport.mjs'])jsHashes[p]=hash(await normalized(p));
const scripts={};for(const p of ['sample.mjs','compare.ps1','summarize.mjs'])scripts[p]={sha256:hash(await normalized(`${dir}/${p}`)),source:await normalized(`${dir}/${p}`)};
const report={date:'2026-10-11',policy:{before:'Native v17',after:'Native v18; coupled CRIT/CRITP support; split v6 unchanged'},environment:{cpu:cpus()[0].model,logicalThreads:cpus().length,node:process.version,platform:process.platform,arch:process.arch},boundary:'compile raw resolved input -> product Native client/service -> restored result and final JS evaluation; UI excluded',method:'10 fresh Node/Native process pairs per input, alternating order, same JS, release, 30s slice, no concurrent tests/builds',memoryBoundary:'Native process peak working set sampled every 25ms; excludes Node/JS; approximate',checks:{exactScoreAndWholeBuildEqual:100,compiledAndPreparedInputEqual:100,finalJsFeasibleAndScoreEqual:100,rawStatSumEqual:100,sourceBinaryHashes:true},stamps,jsHashes,inputs:inputRecords,scripts,summary,runs:rows};
await writeFile('docs/verification/crysta-linear-crit-bound-measurements.json',JSON.stringify(report,null,2)+'\n');
console.log(JSON.stringify(summary,null,2));
